import app from 'flarum/admin/app';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import Icon from 'flarum/common/components/Icon';
import LoadingIndicator from 'flarum/common/components/LoadingIndicator';
const t = (key, params = {}) => app.translator.trans(`ernestdefoe-who-said-it.admin.status.${key}`, params);
/**
 * Today at a glance: whether the quiz is made, how many have played, and how
 * many posts qualify under the settings below. Never shows the quotes — the
 * admin may want to play too.
 */
export default class StatusPanel extends Component {
  status = null;
  busy = false;
  oninit(vnode) {
    super.oninit(vnode);
    this.load('GET');
  }
  load(method) {
    this.busy = method === 'POST';
    app.request({
      method,
      url: app.forum.attribute('apiUrl') + '/who-said-it/admin'
    }).then(status => this.status = status).catch(() => {}).finally(() => {
      this.busy = false;
      m.redraw();
    });
  }
  view() {
    const s = this.status;
    return m("div", {
      className: "Form-group WsiAdminStatus"
    }, m("label", null, t('title')), !s ? m(LoadingIndicator, {
      display: "inline",
      size: "small"
    }) : m("div", {
      className: "WsiAdminStatus-box"
    }, m("p", null, m(Icon, {
      name: s.count ? 'fas fa-circle-check' : 'far fa-circle'
    }), ' ', s.count ? t('made', {
      count: s.count,
      players: s.players,
      date: s.date
    }) : t('not_made', {
      date: s.date
    })), m("p", {
      className: "helpText"
    }, s.eligible >= 1000 ? t('eligible_many') : t('eligible', {
      count: s.eligible
    })), !s.count ? m(Button, {
      className: "Button",
      icon: "fas fa-wand-magic-sparkles",
      loading: this.busy,
      onclick: () => this.load('POST')
    }, t('make')) : null, m("p", {
      className: "helpText"
    }, t('scheduler')), m("p", {
      className: "helpText"
    }, t('members_only'))));
  }
}